def _refill(self):
    t = self._now()
    # Only refill based on elapsed time if we have a previous timestamp.
    # Use explicit None check because 0.0 is a valid timestamp.
    if self._last is not None:
        self._tokens += (t - self._last) * self.rate
        # Don't allow tokens to exceed capacity.
        if self._tokens > self.capacity:
            self._tokens = float(self.capacity)
    self._last = t
